<?php require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';header('Content-Type: application/json; charset=utf-8');header('X-Content-Type-Options: nosniff');$method=$_SERVER['REQUEST_METHOD'];if($method==='GET'){$q=trim($_GET['q']??'');$like='%'.$q.'%';$s=$conn->prepare('SELECT id,name,email,course FROM students WHERE name LIKE ? OR email LIKE ? ORDER BY id DESC LIMIT 100');$s->bind_param('ss',$like,$like);$s->execute();echo json_encode(['data'=>$s->get_result()->fetch_all(MYSQLI_ASSOC)]);exit;}if(!logged_in()||($_SESSION['role']??'')!=='admin'){http_response_code(403);echo json_encode(['error'=>'Admin access required']);exit;}$input=json_decode(file_get_contents('php://input'),true)??[];if($method==='POST'){$name=trim($input['name']??'');$email=filter_var($input['email']??'',FILTER_VALIDATE_EMAIL);$course=trim($input['course']??'Computer Engineering');if(strlen($name)<2||!$email){http_response_code(422);echo json_encode(['error'=>'Valid name and email required']);exit;}$s=$conn->prepare('INSERT INTO students(name,email,course,semester) VALUES(?,?,?,3)');$s->bind_param('sss',$name,$email,$course);if($s->execute()){http_response_code(201);echo json_encode(['id'=>$s->insert_id,'message'=>'Student created']);}else{http_response_code(409);echo json_encode(['error'=>'Could not create student']);}exit;}if($method==='PUT'){$id=(int)($input['id']??0);$name=trim($input['name']??'');$email=filter_var($input['email']??'',FILTER_VALIDATE_EMAIL);$course=trim($input['course']??'Computer Engineering');if($id<1||strlen($name)<2||!$email){http_response_code(422);echo json_encode(['error'=>'Valid id, name and email required']);exit;}$s=$conn->prepare('UPDATE students SET name=?,email=?,course=? WHERE id=?');$s->bind_param('sssi',$name,$email,$course,$id);$s->execute();echo json_encode(['message'=>'Update processed','affected'=>$s->affected_rows]);exit;}if($method==='DELETE'){$id=(int)($input['id']??0);if($id<1){http_response_code(422);echo json_encode(['error'=>'Valid id required']);exit;}$s=$conn->prepare('DELETE FROM students WHERE id=?');$s->bind_param('i',$id);$s->execute();echo json_encode(['message'=>'Delete processed','affected'=>$s->affected_rows]);exit;}header('Allow: GET, POST, PUT, DELETE');http_response_code(405);echo json_encode(['error'=>'Method not allowed']);
